                           const isEditing = editingId === record.id;

                           return (
                             <div key={studentName} className={`rounded-lg p-3 border transition-colors group ${isEditing ? 'bg-white border-indigo-400 ring-2 ring-indigo-100' : 'bg-indigo-50 border-indigo-100'}`}>
                               {isEditing ? (
                                 <div className="space-y-2">
                                   <div className="flex justify-between items-center mb-2">
                                      <span className="font-bold text-gray-900">{studentName}</span>
                                      <span className="text-xs text-indigo-500 font-bold">수정 중...</span>
                                   </div>
                                   <select 
                                     value={editMethod} 
                                     onChange={(e) => setEditMethod(e.target.value)}
                                     className="w-full p-1.5 text-xs border rounded mb-1 bg-white"
                                   >
                                     {DISMISSAL_METHODS.map(m => <option key={m} value={m}>{m}</option>)}
                                   </select>
                                   <div className="flex gap-1 items-center">
                                      <select value={editHour} onChange={(e) => setEditHour(e.target.value)} className="p-1 text-xs border rounded bg-white">
                                        {HOURS.map(h => <option key={h} value={h}>{h}</option>)}
                                      </select>
                                      <span className="text-gray-400">:</span>
                                      <select value={editMinute} onChange={(e) => setEditMinute(e.target.value)} className="p-1 text-xs border rounded bg-white">
                                        {MINUTES.map(m => <option key={m} value={m}>{m}</option>)}
                                      </select>
                                   </div>
                                   <div className="flex gap-2 mt-2 pt-2 border-t border-gray-100">
                                     <button type="button" onClick={() => saveEditing(record)} className="flex-1 py-1 bg-indigo-600 text-white text-xs rounded hover:bg-indigo-700">저장</button>
                                     <button type="button" onClick={cancelEditing} className="flex-1 py-1 bg-gray-200 text-gray-700 text-xs rounded hover:bg-gray-300">취소</button>
                                   </div>
                                 </div>
                               ) : (
                                 <div className="flex justify-between items-center">
                                   <div>
                                     <div className="font-bold text-gray-900">{studentName}</div>
                                     <div className={`text-xs mt-1 ${
                                        record.dismissalMethod === '에듀택시' 
                                          ? 'text-[#9F814F]' 
                                          : record.dismissalMethod === '통학차' 
                                            ? 'text-red-600 font-bold' 
                                            : 'text-indigo-600'
                                      }`}>
                                       {record.dismissalMethod}
                                     </div>
                                   </div>
                                   <div className="text-right flex items-center gap-3">
                                     <div className="text-lg font-bold text-gray-800">
                                       {new Date(record.timestamp).toLocaleTimeString('ko-KR', { hour: '2-digit', minute: '2-digit' })}
                                     </div>
                                     <div className="flex gap-1">
                                        <button
                                          type="button"
                                          onClick={() => startEditing(record)}
                                          className="p-1.5 text-gray-300 hover:text-indigo-500 hover:bg-indigo-50 rounded-md transition-colors relative z-10"
                                          title="기록 수정"
                                        >
                                          <svg className="w-4 h-4 pointer-events-none" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                                          </svg>
                                        </button>
                                        <button
                                          type="button"
                                          onClick={(e) => handleDeleteClick(e, record.id, record.studentName)}
                                          className="p-1.5 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-md transition-colors relative z-20 cursor-pointer"
                                          title="기록 삭제"
                                        >
                                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                                          </svg>
                                        </button>
                                     </div>
                                   </div>
                                 </div>
                               )}
                             </div>
                           );
                         } else {
                           return (
                             <div key={studentName} className="bg-gray-50 rounded-lg p-3 border border-gray-100 flex justify-between items-center opacity-75">
                               <div>
                                 <div className="font-medium text-gray-500">{studentName}</div>
                                 <div className="text-xs text-gray-400 mt-1">-</div>
                               </div>
                               <div className="text-xs text-gray-400 bg-gray-200 px-2 py-1 rounded">
                                 미하교
                               </div>
                             </div>
                           );
                         }
                       })}
                     </div>
                   </div>
                 ))}
               </div>
            </div>

          </div>
        )}
      </main>

      {/* Delete Confirmation Modal */}
      {deleteModal.isOpen && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center px-4 animate-fade-in" 
          onClick={() => !isDeleting && setDeleteModal(prev => ({...prev, isOpen: false}))}
        >
          <div 
            className="bg-white rounded-2xl shadow-2xl p-6 w-full max-w-sm transform transition-all scale-100" 
            onClick={e => e.stopPropagation()}
          >
            <div className="flex items-start gap-4 mb-4">
              <div className="w-12 h-12 rounded-full bg-red-100 flex items-center justify-center flex-shrink-0">
                {isDeleting ? (
                   <svg className="animate-spin h-6 w-6 text-red-600" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                     <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                     <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                   </svg>
                ) : (
                  <svg className="w-6 h-6 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                  </svg>
                )}
              </div>
              <div>
                <h3 className="text-lg font-bold text-gray-900">기록 삭제 확인</h3>
                <p className="text-gray-600 text-sm mt-1">
                  <span className="font-bold text-indigo-600">{deleteModal.name}</span> 학생의 하교 기록을 정말로 삭제하시겠습니까?
                </p>
              </div>
            </div>
            <div className="flex gap-2 mt-2">
              <button 
                type="button"
                disabled={isDeleting}
                onClick={() => setDeleteModal(prev => ({...prev, isOpen: false}))}
                className="flex-1 py-3 text-gray-600 font-medium bg-gray-100 rounded-xl hover:bg-gray-200 transition-colors disabled:opacity-50"
              >
                취소
              </button>
              <button 
                type="button"
                disabled={isDeleting || !deleteModal.id}
                onClick={(e) => {
                  e.stopPropagation();
                  if (deleteModal.id) confirmDelete(deleteModal.id);
                }}
                className="flex-1 py-3 text-white font-bold bg-red-500 rounded-xl hover:bg-red-600 shadow-md hover:shadow-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed flex justify-center items-center"
              >
                {isDeleting ? '삭제 중...' : '삭제하기'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

export interface DismissalRecord {
  id: string;
  studentName: string;
  grade: number;
  dismissalMethod: string;
  timestamp: number;
  message: string;
}

export interface Student {
  id: string;
  name: string;
  grade: number;
}

export type UserRole = 'STUDENT' | 'TEACHER';
export type TeacherView = 'DASHBOARD' | 'ROSTER';

export interface Notification {
  id: string;
  title: string;
  body: string;
  visible: boolean;
}

export interface Source {
  title: string;
  uri: string;
}

export interface LunchData {
  menuText: string;
  sources: Source[];
}

import React, { useState, useEffect, useMemo } from 'react';
import { DismissalRecord, UserRole, Notification, LunchData, Student, TeacherView } from './types';
import { generateGoodbyeMessage, fetchLunchMenu } from './services/geminiService';
import { db } from './services/firebase';
import { collection, addDoc, onSnapshot, query, orderBy, deleteDoc, doc, updateDoc, writeBatch, getDocs } from 'firebase/firestore';

// Declare SheetJS global
declare const XLSX: any;

// --- Default Data for Seeding ---
const INITIAL_STUDENTS: Omit<Student, 'id'>[] = [
  { grade: 1, name: '김건우' }, { grade: 1, name: '김하설' }, { grade: 1, name: '서아인' },
  { grade: 2, name: '김태준' }, { grade: 2, name: '윤재성' }, { grade: 2, name: '윤지수' }, { grade: 2, name: '양혜린' },
  { grade: 3, name: '김온유' }, { grade: 3, name: '박소윤' }, { grade: 3, name: '서유인' },
  { grade: 4, name: '강태양' }, { grade: 4, name: '김다은' }, { grade: 4, name: '박가은' }, { grade: 4, name: '심은정' }, { grade: 4, name: '엄승환' }, { grade: 4, name: '최은율' }, { grade: 4, name: '박초연' },
  { grade: 5, name: '서상준' }, { grade: 5, name: '전지후' }, { grade: 5, name: '차승환' }, { grade: 5, name: '임지효' },
  { grade: 6, name: '강려울' }, { grade: 6, name: '강지온' }, { grade: 6, name: '박민혁' }, { grade: 6, name: '박수정' }, { grade: 6, name: '박시은' }, { grade: 6, name: '차은애' }
];

const DISMISSAL_METHODS = ['통학차', '에듀택시', '시내버스', '공부방 차량', '부모님 차량', '도보'];
const HOURS = ['1', '2', '3', '4'];
const MINUTES = ['00', '10', '20', '30', '40', '50'];

// --- Helper Functions ---
const isSameDate = (date1: Date, date2: Date) => {
  return date1.getFullYear() === date2.getFullYear() &&
         date1.getMonth() === date2.getMonth() &&
         date1.getDate() === date2.getDate();
};

const formatDateForInput = (date: Date) => {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
};

// --- Components ---

const AdminLoginModal = ({ isOpen, onClose, value, onChange, onSubmit }: any) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center px-4">
      <div className="bg-white rounded-2xl shadow-2xl p-6 w-full max-w-sm animate-fade-in">
        <h3 className="text-xl font-bold text-gray-900 mb-2">관리자 로그인</h3>
        <p className="text-sm text-gray-500 mb-4">선생님 전용 관리자 코드를 입력하세요.</p>
        <form onSubmit={onSubmit}>
          <input 
            type="password" 
            value={value}
            onChange={(e) => onChange(e.target.value)}
            placeholder="관리자 코드"
            autoFocus
            className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl mb-4 focus:ring-2 focus:ring-indigo-500 outline-none"
          />
          <div className="flex gap-2">
            <button type="button" onClick={onClose} className="flex-1 py-3 text-gray-600 font-medium bg-gray-100 rounded-xl hover:bg-gray-200">취소</button>
            <button type="submit" className="flex-1 py-3 text-white font-bold bg-indigo-600 rounded-xl hover:bg-indigo-700">확인</button>
          </div>
        </form>
      </div>
    </div>
  );
};

function App() {
  // --- Global State ---
  const [role, setRole] = useState<UserRole>('STUDENT');
  const [teacherView, setTeacherView] = useState<TeacherView>('DASHBOARD');
  const [records, setRecords] = useState<DismissalRecord[]>([]);
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [dbError, setDbError] = useState<string | null>(null);

  // --- Student Form State ---
  const [grade, setGrade] = useState<number>(1);
  const [name, setName] = useState<string>('');
  const [dismissalMethod, setDismissalMethod] = useState<string>(DISMISSAL_METHODS[0]);
  const [hour, setHour] = useState<string>('4');
  const [minute, setMinute] = useState<string>('30');
  const [hasSubmitted, setHasSubmitted] = useState(false);

  // --- Auth & Admin State ---
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminCodeInput, setAdminCodeInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  // --- Lunch State ---
  const [lunchDate, setLunchDate] = useState<Date>(new Date());
  const [lunchInfo, setLunchInfo] = useState<LunchData | null>(null);
  const [lunchLoading, setLunchLoading] = useState(false);

  // --- Roster Management State ---
  const [newStudentName, setNewStudentName] = useState<Record<number, string>>({});

  // --- Effects ---

  // 1. Real-time Students & Records
  useEffect(() => {
    const unsubscribeRecords = onSnapshot(query(collection(db, "dismissals"), orderBy("timestamp", "desc")), (snap) => {
      setRecords(snap.docs.map(d => ({ id: d.id, ...d.data() } as DismissalRecord)));
    });

    const unsubscribeStudents = onSnapshot(query(collection(db, "students"), orderBy("grade", "asc"), orderBy("name", "asc")), async (snap) => {
      if (snap.empty) {
        // Initial Seed if database is empty
        const batch = writeBatch(db);
        INITIAL_STUDENTS.forEach(s => {
          const ref = doc(collection(db, "students"));
          batch.set(ref, s);
        });
        await batch.commit();
      } else {
        setStudents(snap.docs.map(d => ({ id: d.id, ...d.data() } as Student)));
      }
    });

    return () => {
      unsubscribeRecords();
      unsubscribeStudents();
    };
  }, []);

  // 2. Lunch Menu Loader
  useEffect(() => {
    const loadLunch = async () => {
      setLunchLoading(true);
      try {
        const data = await fetchLunchMenu(lunchDate);
        setLunchInfo(data);
      } catch (e) { console.error(e); }
      finally { setLunchLoading(false); }
    };
    loadLunch();
  }, [lunchDate]);

  // --- Logic Helpers ---
  const studentsByGrade = useMemo(() => {
    const grouped: Record<number, Student[]> = {};
    [1,2,3,4,5,6].forEach(g => grouped[g] = students.filter(s => s.grade === g));
    return grouped;
  }, [students]);

  // --- Handlers ---
  const handleRoleButtonClick = (targetRole: UserRole) => {
    if (targetRole === 'TEACHER') {
      setShowAdminLogin(true);
      setAdminCodeInput('');
    } else {
      setRole('STUDENT');
    }
  };

  const handleAdminLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (adminCodeInput === 'hy6516') {
      setRole('TEACHER');
      setShowAdminLogin(false);
    } else {
      alert('올바른 관리자 코드를 입력해 주세요.');
    }
  };

  const handleDismissal = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) return;
    setLoading(true);
    const aiMessage = await generateGoodbyeMessage(name, grade);
    const hours24 = parseInt(hour) + 12;
    const recordDate = new Date();
    recordDate.setHours(hours24, parseInt(minute), 0, 0);

    try {
      await addDoc(collection(db, "dismissals"), {
        studentName: name, grade, dismissalMethod, timestamp: recordDate.getTime(), message: aiMessage
      });
      setHasSubmitted(true);
      setTimeout(() => { setHasSubmitted(false); setName(''); }, 2000);
    } catch (err) { alert("저장 실패"); }
    finally { setLoading(false); }
  };

  // --- Roster Management Handlers ---
  const addStudent = async (gradeLevel: number) => {
    const sName = newStudentName[gradeLevel]?.trim();
    if (!sName) return;
    try {
      await addDoc(collection(db, "students"), { name: sName, grade: gradeLevel });
      setNewStudentName(prev => ({ ...prev, [gradeLevel]: '' }));
    } catch (e) { alert("추가 실패"); }
  };

  const deleteStudent = async (studentId: string) => {
    if (!confirm("이 학생을 명단에서 삭제하시겠습니까?")) return;
    try {
      await deleteDoc(doc(db, "students", studentId));
    } catch (e) { alert("삭제 실패"); }
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 font-sans pb-20">
      <AdminLoginModal 
        isOpen={showAdminLogin} 
        onClose={() => setShowAdminLogin(false)}
        value={adminCodeInput}
        onChange={setAdminCodeInput}
        onSubmit={handleAdminLoginSubmit}
      />

      <header className="bg-white shadow-sm sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold">H</div>
            <h1 className="text-lg md:text-xl font-bold text-gray-900">화양초 하교기록</h1>
          </div>
          <div className="flex bg-gray-100 p-1 rounded-lg">
            <button onClick={() => setRole('STUDENT')} className={`px-4 py-1.5 text-sm font-medium rounded-md transition-all ${role === 'STUDENT' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>학생용</button>
            <button onClick={() => handleRoleButtonClick('TEACHER')} className={`px-4 py-1.5 text-sm font-medium rounded-md transition-all ${role === 'TEACHER' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>교사용</button>
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 py-8">
        {role === 'STUDENT' ? (
          <div className="max-w-md mx-auto space-y-8">
            <div className="text-center space-y-2">
              <p className="text-sm font-semibold text-indigo-600 bg-indigo-50 inline-block px-3 py-1 rounded-full">{new Date().toLocaleDateString('ko-KR', { month: 'long', day: 'numeric', weekday: 'short' })}</p>
              <h2 className="text-2xl font-bold text-gray-900">하교 시간 기록하기</h2>
            </div>

            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium text-gray-500 mb-1">학년</label>
                  <select value={grade} onChange={(e) => setGrade(Number(e.target.value))} className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl outline-none">
                    {[1,2,3,4,5,6].map(g => <option key={g} value={g}>{g}학년</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-medium text-gray-500 mb-1">이름</label>
                  <select value={name} onChange={(e) => setName(e.target.value)} className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl outline-none">
                    <option value="">-- 선택 --</option>
                    {studentsByGrade[grade]?.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 mb-1">하교 방법</label>
                <select value={dismissalMethod} onChange={(e) => setDismissalMethod(e.target.value)} className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl outline-none">
                  {DISMISSAL_METHODS.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <button 
                onClick={handleDismissal}
                disabled={loading || !name || hasSubmitted}
                className={`w-full py-4 rounded-xl text-white font-bold text-lg shadow-lg transition-all ${hasSubmitted ? 'bg-green-500' : loading || !name ? 'bg-indigo-300' : 'bg-indigo-600 hover:bg-indigo-700 active:scale-95'}`}
              >
                {loading ? '처리 중...' : hasSubmitted ? '제출 완료!' : '제출하기'}
              </button>
            </div>

            {/* Student List View */}
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="p-4 bg-gray-50 border-b border-gray-100 font-bold text-gray-700 text-sm">오늘의 하교 현황</div>
              <div className="divide-y divide-gray-100">
                {[1,2,3,4,5,6].map(g => (
                  <div key={g} className="p-4">
                    <h4 className="text-[10px] font-bold text-gray-400 mb-2 uppercase">{g}학년</h4>
                    <div className="flex flex-wrap gap-2">
                      {studentsByGrade[g]?.map(s => {
                        const isDone = records.some(r => r.studentName === s.name && isSameDate(new Date(r.timestamp), new Date()));
                        return (
                          <span key={s.id} className={`px-3 py-1.5 rounded-full text-xs transition-colors ${isDone ? 'bg-indigo-600 text-white font-bold' : 'bg-gray-100 text-gray-400'}`}>
                            {s.name}
                          </span>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Lunch Info Card */}
            <div className="bg-indigo-600 rounded-2xl shadow-lg p-6 text-white overflow-hidden relative">
              <div className="relative z-10">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="font-bold text-lg flex items-center gap-2">🍱 오늘의 급식</h3>
                  <div className="flex items-center gap-2 bg-white bg-opacity-20 rounded-lg p-1">
                    <button onClick={() => setLunchDate(new Date(lunchDate.setDate(lunchDate.getDate()-1)))} className="p-1 hover:bg-white hover:bg-opacity-20 rounded"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15 19l-7-7 7-7" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg></button>
                    <span className="text-xs font-medium px-1">{lunchDate.toLocaleDateString('ko-KR', {month:'short', day:'numeric'})}</span>
                    <button onClick={() => setLunchDate(new Date(lunchDate.setDate(lunchDate.getDate()+1)))} className="p-1 hover:bg-white hover:bg-opacity-20 rounded"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 5l7 7-7 7" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg></button>
                  </div>
                </div>
                {lunchLoading ? <div className="animate-pulse space-y-2"><div className="h-4 bg-white/20 rounded w-3/4"></div><div className="h-4 bg-white/20 rounded w-1/2"></div></div> : (
                  <div className="text-sm bg-white/10 p-4 rounded-xl backdrop-blur-sm border border-white/10 whitespace-pre-wrap leading-relaxed">
                    {lunchInfo?.menuText || "메뉴 정보가 없습니다."}
                  </div>
                )}
              </div>
            </div>
          </div>
        ) : (
          /* ============ TEACHER VIEW ============ */
          <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">교사 관리 모드</h2>
                <p className="text-gray-500 text-sm">하교 현황 확인 및 명단 관리를 수행합니다.</p>
              </div>
              <div className="flex bg-indigo-50 p-1 rounded-xl">
                <button onClick={() => setTeacherView('DASHBOARD')} className={`px-4 py-2 text-sm font-bold rounded-lg transition-all ${teacherView === 'DASHBOARD' ? 'bg-indigo-600 text-white shadow-md' : 'text-indigo-400'}`}>현황 대시보드</button>
                <button onClick={() => setTeacherView('ROSTER')} className={`px-4 py-2 text-sm font-bold rounded-lg transition-all ${teacherView === 'ROSTER' ? 'bg-indigo-600 text-white shadow-md' : 'text-indigo-400'}`}>명렬표 관리</button>
              </div>
            </div>

            {teacherView === 'DASHBOARD' ? (
              <div className="space-y-6 animate-fade-in">
                {/* Search and Date Filter */}
                <div className="flex gap-4">
                  <div className="flex-1 bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex items-center gap-3">
                    <svg className="w-5 h-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" strokeWidth="2"/></svg>
                    <input type="text" placeholder="학생 이름 검색..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full outline-none text-sm"/>
                  </div>
                </div>

                {/* Grid of Grades */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {[1,2,3,4,5,6].map(g => (
                    <div key={g} className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                      <div className="p-4 bg-gray-50 border-b border-gray-100 flex justify-between items-center">
                        <h4 className="font-bold text-gray-800">{g}학년</h4>
                        <span className="text-[10px] bg-indigo-100 text-indigo-600 px-2 py-0.5 rounded-full font-bold">
                          {records.filter(r => r.grade === g && isSameDate(new Date(r.timestamp), selectedDate)).length} / {studentsByGrade[g]?.length}
                        </span>
                      </div>
                      <div className="p-4 space-y-3">
                        {studentsByGrade[g]?.filter(s => s.name.includes(searchTerm)).map(s => {
                          const record = records.find(r => r.studentName === s.name && r.grade === g && isSameDate(new Date(r.timestamp), selectedDate));
                          return (
                            <div key={s.id} className={`flex justify-between items-center p-3 rounded-xl border transition-all ${record ? 'bg-indigo-50 border-indigo-100' : 'bg-gray-50 border-transparent opacity-60'}`}>
                              <div>
                                <div className="font-bold text-sm text-gray-900">{s.name}</div>
                                <div className="text-[10px] text-indigo-500 font-medium">{record?.dismissalMethod || '미하교'}</div>
                              </div>
                              {record && (
                                <div className="text-right">
                                  <div className="text-xs font-bold text-gray-800">{new Date(record.timestamp).toLocaleTimeString('ko-KR', {hour:'2-digit', minute:'2-digit'})}</div>
                                  <button onClick={() => deleteDoc(doc(db, "dismissals", record.id))} className="text-[10px] text-red-400 hover:text-red-600 underline mt-1">기록취소</button>
                                </div>
                              )}
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ) : (
              /* ============ ROSTER MANAGEMENT ============ */
              <div className="space-y-6 animate-fade-in">
                <div className="bg-amber-50 border border-amber-100 p-4 rounded-2xl text-amber-800 text-sm flex gap-3">
                  <span className="text-xl">💡</span>
                  <p>이곳에서 학생 명단을 직접 관리할 수 있습니다. 추가된 학생은 실시간으로 학생용 화면에 반영되며, 내년 신학기 명단으로 교체할 때 매우 유용합니다.</p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {[1,2,3,4,5,6].map(g => (
                    <div key={g} className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
                      <h4 className="text-lg font-bold text-gray-900 mb-4">{g}학년 명단</h4>

                      <div className="flex flex-wrap gap-2 mb-6 min-h-[50px]">
                        {studentsByGrade[g]?.map(s => (
                          <div key={s.id} className="group relative">
                            <span className="inline-flex items-center gap-1 bg-gray-100 text-gray-700 px-3 py-1.5 rounded-full text-sm font-medium border border-gray-200 group-hover:bg-red-50 group-hover:text-red-600 group-hover:border-red-200 transition-all">
                              {s.name}
                              <button onClick={() => deleteStudent(s.id)} className="opacity-0 group-hover:opacity-100 transition-opacity p-0.5 hover:bg-red-200 rounded-full">
                                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
                              </button>
                            </span>
                          </div>
                        ))}
                        {studentsByGrade[g]?.length === 0 && <p className="text-gray-300 text-sm italic">등록된 학생이 없습니다.</p>}
                      </div>

                      <div className="flex gap-2">
                        <input 
                          type="text" 
                          placeholder="새 학생 이름..." 
                          value={newStudentName[g] || ''} 
                          onChange={e => setNewStudentName(prev => ({...prev, [g]: e.target.value}))}
                          onKeyDown={e => e.key === 'Enter' && addStudent(g)}
                          className="flex-1 bg-gray-50 border border-gray-200 rounded-xl px-4 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500"
                        />
                        <button 
                          onClick={() => addStudent(g)}
                          className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-colors"
                        >
                          추가
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { DismissalRecord, UserRole, Notification, LunchData, Student, TeacherView } from './types';
import { generateGoodbyeMessage, fetchLunchMenu } from './services/geminiService';
import { db } from './services/firebase';
import { collection, addDoc, onSnapshot, query, orderBy, deleteDoc, doc, updateDoc, writeBatch } from 'firebase/firestore';

// Declare SheetJS global
declare const XLSX: any;

// --- Default Data for Seeding (Initial setup) ---
const INITIAL_STUDENTS: Omit<Student, 'id'>[] = [
  { grade: 1, name: '김건우' }, { grade: 1, name: '김하설' }, { grade: 1, name: '서아인' },
  { grade: 2, name: '김태준' }, { grade: 2, name: '윤재성' }, { grade: 2, name: '윤지수' }, { grade: 2, name: '양혜린' },
  { grade: 3, name: '김온유' }, { grade: 3, name: '박소윤' }, { grade: 3, name: '서유인' },
  { grade: 4, name: '강태양' }, { grade: 4, name: '김다은' }, { grade: 4, name: '박가은' }, { grade: 4, name: '심은정' }, { grade: 4, name: '엄승환' }, { grade: 4, name: '최은율' }, { grade: 4, name: '박초연' },
  { grade: 5, name: '서상준' }, { grade: 5, name: '전지후' }, { grade: 5, name: '차승환' }, { grade: 5, name: '임지효' },
  { grade: 6, name: '강려울' }, { grade: 6, name: '강지온' }, { grade: 6, name: '박민혁' }, { grade: 6, name: '박수정' }, { grade: 6, name: '박시은' }, { grade: 6, name: '차은애' }
];

const DISMISSAL_METHODS = ['통학차', '에듀택시', '시내버스', '공부방 차량', '부모님 차량', '도보'];
const HOURS = ['1', '2', '3', '4'];
const MINUTES = ['00', '10', '20', '30', '40', '50'];

// --- Helper Functions ---
const isSameDate = (date1: Date, date2: Date) => {
  return date1.getFullYear() === date2.getFullYear() &&
         date1.getMonth() === date2.getMonth() &&
         date1.getDate() === date2.getDate();
};

const formatDateForInput = (date: Date) => {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
};

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

// --- Components ---

const AdminLoginModal = ({ isOpen, onClose, value, onChange, onSubmit }: any) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center px-4">
      <div className="bg-white rounded-2xl shadow-2xl p-6 w-full max-w-sm animate-fade-in">
        <h3 className="text-xl font-bold text-gray-900 mb-2">관리자 로그인</h3>
        <p className="text-sm text-gray-500 mb-4">선생님 전용 관리자 코드를 입력하세요.</p>
        <form onSubmit={onSubmit}>
          <input 
            type="password" 
            value={value}
            onChange={(e) => onChange(e.target.value)}
            placeholder="관리자 코드"
            autoFocus
            className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl mb-4 focus:ring-2 focus:ring-indigo-500 outline-none"
          />
          <div className="flex gap-2">
            <button type="button" onClick={onClose} className="flex-1 py-3 text-gray-600 font-medium bg-gray-100 rounded-xl hover:bg-gray-200">취소</button>
            <button type="submit" className="flex-1 py-3 text-white font-bold bg-indigo-600 rounded-xl hover:bg-indigo-700">확인</button>
          </div>
        </form>
      </div>
    </div>
  );
};

function App() {
  // --- Global State ---
  const [role, setRole] = useState<UserRole>('STUDENT');
  const [teacherView, setTeacherView] = useState<TeacherView>('DASHBOARD');
  const [records, setRecords] = useState<DismissalRecord[]>([]);
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(false);

  // --- Student Form State ---
  const [grade, setGrade] = useState<number>(1);
  const [name, setName] = useState<string>('');
  const [dismissalMethod, setDismissalMethod] = useState<string>(DISMISSAL_METHODS[0]);
  const [hour, setHour] = useState<string>('4');
  const [minute, setMinute] = useState<string>('30');
  const [hasSubmitted, setHasSubmitted] = useState(false);

  // --- Teacher States (Restored) ---
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminCodeInput, setAdminCodeInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [currentCalendarMonth, setCurrentCalendarMonth] = useState<Date>(new Date());
  const [exportStartDate, setExportStartDate] = useState(formatDateForInput(new Date()));
  const [exportEndDate, setExportEndDate] = useState(formatDateForInput(new Date()));
  const [deleteModal, setDeleteModal] = useState<{isOpen: boolean, id: string | null, name: string}>({ isOpen: false, id: null, name: '' });
  const [isDeleting, setIsDeleting] = useState(false);

  // --- Lunch State ---
  const [lunchDate, setLunchDate] = useState<Date>(new Date());
  const [lunchInfo, setLunchInfo] = useState<LunchData | null>(null);
  const [lunchLoading, setLunchLoading] = useState(false);

  // --- Roster Management State ---
  const [newStudentName, setNewStudentName] = useState<Record<number, string>>({});

  // --- Effects ---

  useEffect(() => {
    const unsubscribeRecords = onSnapshot(query(collection(db, "dismissals"), orderBy("timestamp", "desc")), (snap) => {
      setRecords(snap.docs.map(d => ({ id: d.id, ...d.data() } as DismissalRecord)));
    });

    const unsubscribeStudents = onSnapshot(query(collection(db, "students"), orderBy("grade", "asc"), orderBy("name", "asc")), async (snap) => {
      if (snap.empty) {
        const batch = writeBatch(db);
        INITIAL_STUDENTS.forEach(s => {
          const ref = doc(collection(db, "students"));
          batch.set(ref, s);
        });
        await batch.commit();
      } else {
        setStudents(snap.docs.map(d => ({ id: d.id, ...d.data() } as Student)));
      }
    });

    return () => {
      unsubscribeRecords();
      unsubscribeStudents();
    };
  }, []);

  useEffect(() => {
    const loadLunch = async () => {
      setLunchLoading(true);
      try {
        const data = await fetchLunchMenu(lunchDate);
        setLunchInfo(data);
      } catch (e) { console.error(e); }
      finally { setLunchLoading(false); }
    };
    loadLunch();
  }, [lunchDate]);

  // --- Logic Helpers ---
  const studentsByGrade = useMemo(() => {
    const grouped: Record<number, Student[]> = {};
    [1,2,3,4,5,6].forEach(g => grouped[g] = students.filter(s => s.grade === g));
    return grouped;
  }, [students]);

  // --- Handlers ---
  const handleAdminLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (adminCodeInput === 'hy6516') {
      setRole('TEACHER');
      setShowAdminLogin(false);
    } else {
      alert('올바른 관리자 코드를 입력해 주세요.');
    }
  };

  const handleDismissal = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) return;
    setLoading(true);
    const aiMessage = await generateGoodbyeMessage(name, grade);
    const hours24 = parseInt(hour) + 12;
    const recordDate = new Date();
    recordDate.setHours(hours24, parseInt(minute), 0, 0);

    try {
      await addDoc(collection(db, "dismissals"), {
        studentName: name, grade, dismissalMethod, timestamp: recordDate.getTime(), message: aiMessage
      });
      setHasSubmitted(true);
      setTimeout(() => { setHasSubmitted(false); setName(''); }, 2000);
    } catch (err) { alert("저장 실패"); }
    finally { setLoading(false); }
  };

  const handleExcelExport = () => {
    if (typeof XLSX === 'undefined') return alert('라이브러리 로딩 중입니다.');
    const start = new Date(exportStartDate); start.setHours(0,0,0,0);
    const end = new Date(exportEndDate); end.setHours(23,59,59,999);
    const targetRecords = records.filter(r => r.timestamp >= start.getTime() && r.timestamp <= end.getTime());
    if (targetRecords.length === 0) return alert('기록이 없습니다.');

    const excelData = targetRecords.map(r => ({
      '날짜': new Date(r.timestamp).toLocaleDateString('ko-KR'),
      '시간': new Date(r.timestamp).toLocaleTimeString('ko-KR', { hour: '2-digit', minute: '2-digit' }),
      '학년': `${r.grade}학년`,
      '이름': r.studentName,
      '하교방법': r.dismissalMethod,
      'AI 메시지': r.message
    }));

    const ws = XLSX.utils.json_to_sheet(excelData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "하교기록");
    XLSX.writeFile(wb, `하교기록_${exportStartDate}_${exportEndDate}.xlsx`);
  };

  const confirmDelete = async (targetId: string) => {
    setIsDeleting(true);
    try {
      await deleteDoc(doc(db, "dismissals", targetId));
      setDeleteModal({ isOpen: false, id: null, name: '' });
    } catch (e) { alert("삭제 실패"); }
    finally { setIsDeleting(false); }
  };

  const addStudent = async (gradeLevel: number) => {
    const sName = newStudentName[gradeLevel]?.trim();
    if (!sName) return;
    try {
      await addDoc(collection(db, "students"), { name: sName, grade: gradeLevel });
      setNewStudentName(prev => ({ ...prev, [gradeLevel]: '' }));
    } catch (e) { alert("추가 실패"); }
  };

  const deleteStudentFromRoster = async (studentId: string) => {
    if (!confirm("이 학생을 명단에서 삭제하시겠습니까?")) return;
    try {
      await deleteDoc(doc(db, "students", studentId));
    } catch (e) { alert("삭제 실패"); }
  };

  const renderCalendar = () => {
    const year = currentCalendarMonth.getFullYear();
    const month = currentCalendarMonth.getMonth();
    const days = [];
    for (let i = 0; i < getFirstDayOfMonth(year, month); i++) days.push(<div key={`empty-${i}`}></div>);
    for (let d = 1; d <= getDaysInMonth(year, month); d++) {
      const date = new Date(year, month, d);
      const isSelected = isSameDate(date, selectedDate);
      days.push(
        <button key={d} onClick={() => setSelectedDate(date)} className={`h-9 w-9 rounded-full flex items-center justify-center text-sm font-medium transition-all ${isSelected ? 'bg-indigo-600 text-white' : 'hover:bg-indigo-50 text-gray-700'}`}>
          {d}
        </button>
      );
    }
    return days;
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 font-sans pb-20">
      <AdminLoginModal isOpen={showAdminLogin} onClose={() => setShowAdminLogin(false)} value={adminCodeInput} onChange={setAdminCodeInput} onSubmit={handleAdminLoginSubmit} />

      {/* Header */}
      <header className="bg-white shadow-sm sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold">H</div>
            <h1 className="text-lg font-bold text-gray-900">화양초 하교관리</h1>
          </div>
          <div className="flex bg-gray-100 p-1 rounded-lg">
            <button onClick={() => setRole('STUDENT')} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${role === 'STUDENT' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>학생용</button>
            <button onClick={() => { setShowAdminLogin(true); setAdminCodeInput(''); }} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${role === 'TEACHER' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>교사용</button>
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 py-8">
        {role === 'STUDENT' ? (
          <div className="max-w-md mx-auto space-y-8 animate-fade-in">
            <div className="text-center space-y-2">
              <p className="text-sm font-semibold text-indigo-600 bg-indigo-50 inline-block px-3 py-1 rounded-full">{new Date().toLocaleDateString('ko-KR', { month: 'long', day: 'numeric', weekday: 'short' })}</p>
              <h2 className="text-2xl font-bold text-gray-900">하교 시간 기록하기</h2>
            </div>

            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-gray-400 mb-1 uppercase">학년</label>
                  <select value={grade} onChange={(e) => setGrade(Number(e.target.value))} className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl outline-none">
                    {[1,2,3,4,5,6].map(g => <option key={g} value={g}>{g}학년</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-gray-400 mb-1 uppercase">이름</label>
                  <select value={name} onChange={(e) => setName(e.target.value)} className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl outline-none">
                    <option value="">-- 선택 --</option>
                    {studentsByGrade[grade]?.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                  </select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-gray-400 mb-1 uppercase">하교 방법</label>
                  <select value={dismissalMethod} onChange={(e) => setDismissalMethod(e.target.value)} className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl outline-none">
                    {DISMISSAL_METHODS.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
                <div>
                   <label className="block text-[10px] font-bold text-gray-400 mb-1 uppercase">하교 시간</label>
                   <div className="flex gap-1 items-center bg-gray-50 border border-gray-200 rounded-xl p-2.5">
                      <select value={hour} onChange={e => setHour(e.target.value)} className="bg-transparent outline-none font-bold text-sm">{HOURS.map(h => <option key={h} value={h}>{h}시</option>)}</select>
                      <span className="text-gray-300">:</span>
                      <select value={minute} onChange={e => setMinute(e.target.value)} className="bg-transparent outline-none font-bold text-sm">{MINUTES.map(m => <option key={m} value={m}>{m}분</option>)}</select>
                   </div>
                </div>
              </div>
              <button onClick={handleDismissal} disabled={loading || !name || hasSubmitted} className={`w-full py-4 rounded-xl text-white font-bold text-lg shadow-lg transition-all ${hasSubmitted ? 'bg-green-500' : loading || !name ? 'bg-indigo-300' : 'bg-indigo-600 hover:bg-indigo-700 active:scale-95'}`}>
                {loading ? '처리 중...' : hasSubmitted ? '제출 완료!' : '제출하기'}
              </button>
            </div>

            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="p-4 bg-gray-50 border-b border-gray-100 font-bold text-gray-700 text-sm">오늘의 하교 현황</div>
              <div className="divide-y divide-gray-100">
                {[1,2,3,4,5,6].map(g => (
                  <div key={g} className="p-4">
                    <h4 className="text-[10px] font-bold text-gray-400 mb-2 uppercase">{g}학년</h4>
                    <div className="flex flex-wrap gap-2">
                      {studentsByGrade[g]?.map(s => {
                        const isDone = records.some(r => r.studentName === s.name && isSameDate(new Date(r.timestamp), new Date()));
                        return <span key={s.id} className={`px-3 py-1.5 rounded-full text-xs transition-colors ${isDone ? 'bg-indigo-600 text-white font-bold' : 'bg-gray-100 text-gray-400'}`}>{s.name}</span>;
                      })}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="bg-indigo-600 rounded-2xl shadow-lg p-6 text-white overflow-hidden relative">
              <div className="flex justify-between items-center mb-4">
                <h3 className="font-bold text-lg flex items-center gap-2">🍱 오늘의 급식</h3>
                <div className="flex items-center gap-2 bg-white bg-opacity-20 rounded-lg p-1">
                  <button onClick={() => setLunchDate(new Date(lunchDate.setDate(lunchDate.getDate()-1)))} className="p-1"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15 19l-7-7 7-7" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg></button>
                  <span className="text-xs font-medium px-1">{lunchDate.toLocaleDateString('ko-KR', {month:'short', day:'numeric'})}</span>
                  <button onClick={() => setLunchDate(new Date(lunchDate.setDate(lunchDate.getDate()+1)))} className="p-1"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 5l7 7-7 7" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg></button>
                </div>
              </div>
              {lunchLoading ? <div className="animate-pulse h-20 bg-white/10 rounded-xl"></div> : <div className="text-sm bg-white/10 p-4 rounded-xl backdrop-blur-sm whitespace-pre-wrap leading-relaxed">{lunchInfo?.menuText || "메뉴 정보가 없습니다."}</div>}
            </div>
          </div>
        ) : (
          /* ============ TEACHER VIEW (Restored & Integrated) ============ */
          <div className="space-y-6 animate-fade-in">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">교사 관리 모드</h2>
                <p className="text-gray-500 text-sm">하교 데이터 관리 및 학생 명렬표 수정을 수행합니다.</p>
              </div>
              <div className="flex bg-indigo-50 p-1 rounded-xl">
                <button onClick={() => setTeacherView('DASHBOARD')} className={`px-4 py-2 text-sm font-bold rounded-lg transition-all ${teacherView === 'DASHBOARD' ? 'bg-indigo-600 text-white shadow-md' : 'text-indigo-400'}`}>현황 대시보드</button>
                <button onClick={() => setTeacherView('ROSTER')} className={`px-4 py-2 text-sm font-bold rounded-lg transition-all ${teacherView === 'ROSTER' ? 'bg-indigo-600 text-white shadow-md' : 'text-indigo-400'}`}>명단 관리</button>
              </div>
            </div>

            {teacherView === 'DASHBOARD' ? (
              <div className="space-y-6">
                {/* Export Tools */}
                <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 flex flex-col md:flex-row gap-4 items-end">
                   <div className="flex-1 w-full"><label className="text-[10px] font-bold text-gray-400">시작일</label><input type="date" value={exportStartDate} onChange={e => setExportStartDate(e.target.value)} className="w-full p-2 border border-gray-200 rounded-lg text-sm outline-none"/></div>
                   <div className="flex-1 w-full"><label className="text-[10px] font-bold text-gray-400">종료일</label><input type="date" value={exportEndDate} onChange={e => setExportEndDate(e.target.value)} className="w-full p-2 border border-gray-200 rounded-lg text-sm outline-none"/></div>
                   <button onClick={handleExcelExport} className="bg-emerald-600 text-white px-6 py-2 rounded-lg font-bold text-sm hover:bg-emerald-700 flex items-center gap-2 transition-all"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" strokeWidth="2"/></svg>엑셀 내보내기</button>
                </div>

                {/* Calendar & Details */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="md:col-span-1 bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
                    <div className="flex justify-between items-center mb-4">
                      <button onClick={() => setCurrentCalendarMonth(new Date(currentCalendarMonth.getFullYear(), currentCalendarMonth.getMonth()-1, 1))}><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15 19l-7-7 7-7" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg></button>
                      <h4 className="font-bold text-sm">{currentCalendarMonth.getFullYear()}년 {currentCalendarMonth.getMonth()+1}월</h4>
                      <button onClick={() => setCurrentCalendarMonth(new Date(currentCalendarMonth.getFullYear(), currentCalendarMonth.getMonth()+1, 1))}><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 5l7 7-7 7" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg></button>
                    </div>
                    <div className="grid grid-cols-7 gap-1 place-items-center">{renderCalendar()}</div>
                  </div>

                  <div className="md:col-span-2 bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                    <div className="p-4 bg-gray-50 border-b border-gray-100 flex justify-between items-center">
                      <h4 className="font-bold text-sm text-gray-700">{selectedDate.toLocaleDateString('ko-KR')} 하교 리포트</h4>
                      <input type="text" placeholder="이름 검색..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="text-xs border rounded-lg px-2 py-1 outline-none"/>
                    </div>
                    <div className="max-h-[500px] overflow-y-auto divide-y divide-gray-50">
                      {[1,2,3,4,5,6].map(g => (
                        <div key={g} className="p-4">
                          <h5 className="text-[10px] font-bold text-indigo-400 mb-3 uppercase tracking-widest">{g}학년</h5>
                          <div className="space-y-2">
                            {studentsByGrade[g]?.filter(s => s.name.includes(searchTerm)).map(s => {
                              const record = records.find(r => r.studentName === s.name && r.grade === g && isSameDate(new Date(r.timestamp), selectedDate));
                              return (
                                <div key={s.id} className={`flex justify-between items-center p-3 rounded-xl border transition-all ${record ? 'bg-indigo-50 border-indigo-100' : 'bg-gray-50 border-transparent opacity-60'}`}>
                                  <div>
                                    <div className="font-bold text-sm text-gray-900">{s.name}</div>
                                    <div className="text-[10px] text-indigo-500 font-medium">{record?.dismissalMethod || '기록 없음'}</div>
                                  </div>
                                  {record && (
                                    <div className="flex items-center gap-4">
                                      <div className="text-right">
                                        <div className="text-xs font-bold text-gray-800">{new Date(record.timestamp).toLocaleTimeString('ko-KR', {hour:'2-digit', minute:'2-digit'})}</div>
                                      </div>
                                      <button onClick={() => setDeleteModal({isOpen: true, id: record.id, name: s.name})} className="text-red-300 hover:text-red-500 transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" strokeWidth="2"/></svg></button>
                                    </div>
                                  )}
                                </div>
                              );
                            })}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            ) : (
              /* ============ ROSTER MANAGEMENT (Integrated) ============ */
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-fade-in">
                {[1,2,3,4,5,6].map(g => (
                  <div key={g} className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
                    <h4 className="text-lg font-bold text-gray-900 mb-4">{g}학년 명단 수정</h4>
                    <div className="flex flex-wrap gap-2 mb-6 min-h-[50px]">
                      {studentsByGrade[g]?.map(s => (
                        <span key={s.id} className="group inline-flex items-center gap-1 bg-gray-100 text-gray-700 px-3 py-1.5 rounded-full text-sm font-medium border border-gray-200 hover:bg-red-50 hover:text-red-600 hover:border-red-200 transition-all">
                          {s.name}
                          <button onClick={() => deleteStudentFromRoster(s.id)} className="opacity-0 group-hover:opacity-100 transition-opacity"><svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg></button>
                        </span>
                      ))}
                    </div>
                    <div className="flex gap-2">
                      <input type="text" placeholder="새 학생..." value={newStudentName[g] || ''} onChange={e => setNewStudentName(prev => ({...prev, [g]: e.target.value}))} onKeyDown={e => e.key === 'Enter' && addStudent(g)} className="flex-1 bg-gray-50 border border-gray-200 rounded-xl px-4 py-2 text-sm outline-none"/>
                      <button onClick={() => addStudent(g)} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-colors">추가</button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </main>

      {/* Delete Modal */}
      {deleteModal.isOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center px-4 animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl p-6 w-full max-w-sm">
            <h3 className="text-lg font-bold text-gray-900 mb-2">하교 기록 삭제</h3>
            <p className="text-sm text-gray-500 mb-6"><span className="font-bold text-indigo-600">{deleteModal.name}</span> 학생의 하교 기록을 삭제하시겠습니까?</p>
            <div className="flex gap-2">
              <button disabled={isDeleting} onClick={() => setDeleteModal({isOpen: false, id: null, name: ''})} className="flex-1 py-3 text-gray-600 font-medium bg-gray-100 rounded-xl">취소</button>
              <button disabled={isDeleting} onClick={() => deleteModal.id && confirmDelete(deleteModal.id)} className="flex-1 py-3 text-white font-bold bg-red-500 rounded-xl">{isDeleting ? '삭제 중...' : '삭제하기'}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { DismissalRecord, UserRole, Notification, LunchData, Student, TeacherView } from './types';
import { generateGoodbyeMessage, fetchLunchMenu } from './services/geminiService';
import { db } from './services/firebase';
import { collection, addDoc, onSnapshot, query, orderBy, deleteDoc, doc, updateDoc, writeBatch, getDocs } from 'firebase/firestore';

// Declare SheetJS global
declare const XLSX: any;

// --- Default Data for Seeding ---
const INITIAL_STUDENTS: Omit<Student, 'id'>[] = [
  { grade: 1, name: '김건우' }, { grade: 1, name: '김하설' }, { grade: 1, name: '서아인' },
  { grade: 2, name: '김태준' }, { grade: 2, name: '윤재성' }, { grade: 2, name: '윤지수' }, { grade: 2, name: '양혜린' },
  { grade: 3, name: '김온유' }, { grade: 3, name: '박소윤' }, { grade: 3, name: '서유인' },
  { grade: 4, name: '강태양' }, { grade: 4, name: '김다은' }, { grade: 4, name: '박가은' }, { grade: 4, name: '심은정' }, { grade: 4, name: '엄승환' }, { grade: 4, name: '최은율' }, { grade: 4, name: '박초연' },
  { grade: 5, name: '서상준' }, { grade: 5, name: '전지후' }, { grade: 5, name: '차승환' }, { grade: 5, name: '임지효' },
  { grade: 6, name: '강려울' }, { grade: 6, name: '강지온' }, { grade: 6, name: '박민혁' }, { grade: 6, name: '박수정' }, { grade: 6, name: '박시은' }, { grade: 6, name: '차은애' }
];

const DISMISSAL_METHODS = ['통학차', '에듀택시', '시내버스', '공부방 차량', '부모님 차량', '도보'];
const HOURS = ['1', '2', '3', '4'];
const MINUTES = ['00', '10', '20', '30', '40', '50'];

// --- Helper Functions ---
const isSameDate = (date1: Date, date2: Date) => {
  return date1.getFullYear() === date2.getFullYear() &&
         date1.getMonth() === date2.getMonth() &&
         date1.getDate() === date2.getDate();
};

const formatDateForInput = (date: Date) => {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
};

const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();

// --- Components ---

const AdminLoginModal = ({ isOpen, onClose, value, onChange, onSubmit }: any) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center px-4">
      <div className="bg-white rounded-2xl shadow-2xl p-6 w-full max-w-sm animate-fade-in">
        <h3 className="text-xl font-bold text-gray-900 mb-2">관리자 로그인</h3>
        <p className="text-sm text-gray-500 mb-4">선생님 전용 관리자 코드를 입력하세요.</p>
        <form onSubmit={onSubmit}>
          <input 
            type="password" 
            value={value}
            onChange={(e) => onChange(e.target.value)}
            placeholder="관리자 코드"
            autoFocus
            className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl mb-4 focus:ring-2 focus:ring-indigo-500 outline-none"
          />
          <div className="flex gap-2">
            <button type="button" onClick={onClose} className="flex-1 py-3 text-gray-600 font-medium bg-gray-100 rounded-xl hover:bg-gray-200">취소</button>
            <button type="submit" className="flex-1 py-3 text-white font-bold bg-indigo-600 rounded-xl hover:bg-indigo-700">확인</button>
          </div>
        </form>
      </div>
    </div>
  );
};

function App() {
  // --- Global State ---
  const [role, setRole] = useState<UserRole>('STUDENT');
  const [teacherView, setTeacherView] = useState<TeacherView>('DASHBOARD');
  const [records, setRecords] = useState<DismissalRecord[]>([]);
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(false);

  // --- Student Form State ---
  const [grade, setGrade] = useState<number>(1);
  const [name, setName] = useState<string>('');
  const [dismissalMethod, setDismissalMethod] = useState<string>(DISMISSAL_METHODS[0]);
  const [hour, setHour] = useState<string>('4');
  const [minute, setMinute] = useState<string>('30');
  const [hasSubmitted, setHasSubmitted] = useState(false);

  // --- Teacher States ---
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminCodeInput, setAdminCodeInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [currentCalendarMonth, setCurrentCalendarMonth] = useState<Date>(new Date());
  const [exportStartDate, setExportStartDate] = useState(formatDateForInput(new Date()));
  const [exportEndDate, setExportEndDate] = useState(formatDateForInput(new Date()));
  const [deleteModal, setDeleteModal] = useState<{isOpen: boolean, id: string | null, name: string}>({ isOpen: false, id: null, name: '' });
  const [isDeleting, setIsDeleting] = useState(false);

  // --- Lunch State ---
  const [lunchDate, setLunchDate] = useState<Date>(new Date());
  const [lunchInfo, setLunchInfo] = useState<LunchData | null>(null);
  const [lunchLoading, setLunchLoading] = useState(false);

  // --- Roster Management State ---
  const [newStudentName, setNewStudentName] = useState<Record<number, string>>({});
  const [isAddingStudent, setIsAddingStudent] = useState<Record<number, boolean>>({});

  // --- Effects ---

  useEffect(() => {
    // 1. 하교 기록 실시간 수신
    const unsubscribeRecords = onSnapshot(query(collection(db, "dismissals"), orderBy("timestamp", "desc")), (snap) => {
      setRecords(snap.docs.map(d => ({ id: d.id, ...d.data() } as DismissalRecord)));
    }, (error) => console.error("Records Snapshot Error:", error));

    // 2. 학생 명단 실시간 수신 (정렬 지침 제거하여 Index 오류 방지)
    const unsubscribeStudents = onSnapshot(collection(db, "students"), async (snap) => {
      if (snap.empty) {
        // 데이터가 없는 경우 초기값 시딩
        const batch = writeBatch(db);
        INITIAL_STUDENTS.forEach(s => {
          const ref = doc(collection(db, "students"));
          batch.set(ref, s);
        });
        await batch.commit();
      } else {
        const loadedStudents = snap.docs.map(d => ({ id: d.id, ...d.data() } as Student));
        // 메모리에서 정렬 (학년순 -> 이름순)
        const sorted = loadedStudents.sort((a, b) => {
          if (a.grade !== b.grade) return a.grade - b.grade;
          return a.name.localeCompare(b.name, 'ko-KR');
        });
        setStudents(sorted);
      }
    }, (error) => console.error("Students Snapshot Error:", error));

    return () => {
      unsubscribeRecords();
      unsubscribeStudents();
    };
  }, []);

  useEffect(() => {
    const loadLunch = async () => {
      setLunchLoading(true);
      try {
        const data = await fetchLunchMenu(lunchDate);
        setLunchInfo(data);
      } catch (e) { console.error(e); }
      finally { setLunchLoading(false); }
    };
    loadLunch();
  }, [lunchDate]);

  // --- Logic Helpers ---
  const studentsByGrade = useMemo(() => {
    const grouped: Record<number, Student[]> = {};
    [1,2,3,4,5,6].forEach(g => grouped[g] = students.filter(s => s.grade === g));
    return grouped;
  }, [students]);

  // --- Handlers ---
  const handleAdminLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (adminCodeInput === 'hy6516') {
      setRole('TEACHER');
      setShowAdminLogin(false);
    } else {
      alert('올바른 관리자 코드를 입력해 주세요.');
    }
  };

  const handleDismissal = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name) return;
    setLoading(true);
    const aiMessage = await generateGoodbyeMessage(name, grade);
    const hours24 = parseInt(hour) + 12;
    const recordDate = new Date();
    recordDate.setHours(hours24, parseInt(minute), 0, 0);

    try {
      await addDoc(collection(db, "dismissals"), {
        studentName: name, grade, dismissalMethod, timestamp: recordDate.getTime(), message: aiMessage
      });
      setHasSubmitted(true);
      setTimeout(() => { setHasSubmitted(false); setName(''); }, 2000);
    } catch (err) { alert("저장 실패"); }
    finally { setLoading(false); }
  };

  const handleExcelExport = () => {
    if (typeof XLSX === 'undefined') return alert('라이브러리 로딩 중입니다.');
    const start = new Date(exportStartDate); start.setHours(0,0,0,0);
    const end = new Date(exportEndDate); end.setHours(23,59,59,999);
    const targetRecords = records.filter(r => r.timestamp >= start.getTime() && r.timestamp <= end.getTime());
    if (targetRecords.length === 0) return alert('기록이 없습니다.');

    const excelData = targetRecords.map(r => ({
      '날짜': new Date(r.timestamp).toLocaleDateString('ko-KR'),
      '시간': new Date(r.timestamp).toLocaleTimeString('ko-KR', { hour: '2-digit', minute: '2-digit' }),
      '학년': `${r.grade}학년`,
      '이름': r.studentName,
      '하교방법': r.dismissalMethod,
      'AI 메시지': r.message
    }));

    const ws = XLSX.utils.json_to_sheet(excelData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "하교기록");
    XLSX.writeFile(wb, `하교기록_${exportStartDate}_${exportEndDate}.xlsx`);
  };

  const confirmDelete = async (targetId: string) => {
    setIsDeleting(true);
    try {
      await deleteDoc(doc(db, "dismissals", targetId));
      setDeleteModal({ isOpen: false, id: null, name: '' });
    } catch (e) { alert("삭제 실패"); }
    finally { setIsDeleting(false); }
  };

  // --- Roster Handlers ---
  const addStudent = async (gradeLevel: number) => {
    const sName = newStudentName[gradeLevel]?.trim();
    if (!sName) return;

    setIsAddingStudent(prev => ({ ...prev, [gradeLevel]: true }));
    try {
      await addDoc(collection(db, "students"), { 
        name: sName, 
        grade: gradeLevel 
      });
      setNewStudentName(prev => ({ ...prev, [gradeLevel]: '' }));
    } catch (e) { 
      console.error(e);
      alert("학생 추가 중 오류가 발생했습니다."); 
    } finally {
      setIsAddingStudent(prev => ({ ...prev, [gradeLevel]: false }));
    }
  };

  const deleteStudentFromRoster = async (studentId: string) => {
    if (!confirm("이 학생을 명단에서 삭제하시겠습니까?")) return;
    try {
      await deleteDoc(doc(db, "students", studentId));
    } catch (e) { alert("삭제 실패"); }
  };

  const renderCalendar = () => {
    const year = currentCalendarMonth.getFullYear();
    const month = currentCalendarMonth.getMonth();
    const days = [];
    for (let i = 0; i < getFirstDayOfMonth(year, month); i++) days.push(<div key={`empty-${i}`}></div>);
    for (let d = 1; d <= getDaysInMonth(year, month); d++) {
      const date = new Date(year, month, d);
      const isSelected = isSameDate(date, selectedDate);
      days.push(
        <button key={d} onClick={() => setSelectedDate(date)} className={`h-9 w-9 rounded-full flex items-center justify-center text-sm font-medium transition-all ${isSelected ? 'bg-indigo-600 text-white' : 'hover:bg-indigo-50 text-gray-700'}`}>
          {d}
        </button>
      );
    }
    return days;
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 font-sans pb-20">
      <AdminLoginModal isOpen={showAdminLogin} onClose={() => setShowAdminLogin(false)} value={adminCodeInput} onChange={setAdminCodeInput} onSubmit={handleAdminLoginSubmit} />

      {/* Header */}
      <header className="bg-white shadow-sm sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold">H</div>
            <h1 className="text-lg font-bold text-gray-900">화양초 하교관리</h1>
          </div>
          <div className="flex bg-gray-100 p-1 rounded-lg">
            <button onClick={() => setRole('STUDENT')} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${role === 'STUDENT' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>학생용</button>
            <button onClick={() => { setShowAdminLogin(true); setAdminCodeInput(''); }} className={`px-4 py-1.5 text-xs font-bold rounded-md transition-all ${role === 'TEACHER' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>교사용</button>
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 py-8">
        {role === 'STUDENT' ? (
          <div className="max-w-md mx-auto space-y-8 animate-fade-in">
            {/* 학생용 입력 화면 - 기존과 동일 */}
            <div className="text-center space-y-2">
              <p className="text-sm font-semibold text-indigo-600 bg-indigo-50 inline-block px-3 py-1 rounded-full">{new Date().toLocaleDateString('ko-KR', { month: 'long', day: 'numeric', weekday: 'short' })}</p>
              <h2 className="text-2xl font-bold text-gray-900">하교 시간 기록하기</h2>
            </div>

            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-gray-400 mb-1 uppercase">학년</label>
                  <select value={grade} onChange={(e) => setGrade(Number(e.target.value))} className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl outline-none">
                    {[1,2,3,4,5,6].map(g => <option key={g} value={g}>{g}학년</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-gray-400 mb-1 uppercase">이름</label>
                  <select value={name} onChange={(e) => setName(e.target.value)} className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl outline-none">
                    <option value="">-- 선택 --</option>
                    {studentsByGrade[grade]?.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                  </select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-gray-400 mb-1 uppercase">하교 방법</label>
                  <select value={dismissalMethod} onChange={(e) => setDismissalMethod(e.target.value)} className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl outline-none">
                    {DISMISSAL_METHODS.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
                <div>
                   <label className="block text-[10px] font-bold text-gray-400 mb-1 uppercase">하교 시간</label>
                   <div className="flex gap-1 items-center bg-gray-50 border border-gray-200 rounded-xl p-2.5">
                      <select value={hour} onChange={e => setHour(e.target.value)} className="bg-transparent outline-none font-bold text-sm">{HOURS.map(h => <option key={h} value={h}>{h}시</option>)}</select>
                      <span className="text-gray-300">:</span>
                      <select value={minute} onChange={e => setMinute(e.target.value)} className="bg-transparent outline-none font-bold text-sm">{MINUTES.map(m => <option key={m} value={m}>{m}분</option>)}</select>
                   </div>
                </div>
              </div>
              <button onClick={handleDismissal} disabled={loading || !name || hasSubmitted} className={`w-full py-4 rounded-xl text-white font-bold text-lg shadow-lg transition-all ${hasSubmitted ? 'bg-green-500' : loading || !name ? 'bg-indigo-300' : 'bg-indigo-600 hover:bg-indigo-700 active:scale-95'}`}>
                {loading ? '처리 중...' : hasSubmitted ? '제출 완료!' : '제출하기'}
              </button>
            </div>
            {/* 현황 리스트 및 급식 정보 */}
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="p-4 bg-gray-50 border-b border-gray-100 font-bold text-gray-700 text-sm">오늘의 하교 현황</div>
              <div className="divide-y divide-gray-100">
                {[1,2,3,4,5,6].map(g => (
                  <div key={g} className="p-4">
                    <h4 className="text-[10px] font-bold text-gray-400 mb-2 uppercase">{g}학년</h4>
                    <div className="flex flex-wrap gap-2">
                      {studentsByGrade[g]?.map(s => {
                        const isDone = records.some(r => r.studentName === s.name && isSameDate(new Date(r.timestamp), new Date()));
                        return <span key={s.id} className={`px-3 py-1.5 rounded-full text-xs transition-colors ${isDone ? 'bg-indigo-600 text-white font-bold' : 'bg-gray-100 text-gray-400'}`}>{s.name}</span>;
                      })}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        ) : (
          /* ============ TEACHER VIEW ============ */
          <div className="space-y-6 animate-fade-in">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">교사 관리 모드</h2>
