                        const isDone = records.some(r => r.studentName === s.name && isSameDate(new Date(r.timestamp), new Date()));
                        return <span key={s.id} className={`px-3 py-1.5 rounded-full text-xs transition-colors ${isDone ? 'bg-indigo-600 text-white font-bold shadow-sm' : 'bg-gray-100 text-gray-400'}`}>{s.name}</span>;
