                <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 flex flex-col md:flex-row gap-4 items-end">
                   <div className="flex-1 w-full"><label className="text-[10px] font-bold text-gray-400">조회 시작일</label><input type="date" value={exportStartDate} onChange={e => setExportStartDate(e.target.value)} className="w-full p-2.5 border border-gray-200 rounded-lg text-sm outline-none focus:ring-2 focus:ring-indigo-100 transition-all"/></div>
                   <div className="flex-1 w-full"><label className="text-[10px] font-bold text-gray-400">조회 종료일</label><input type="date" value={exportEndDate} onChange={e => setExportEndDate(e.target.value)} className="w-full p-2.5 border border-gray-200 rounded-lg text-sm outline-none focus:ring-2 focus:ring-indigo-100 transition-all"/></div>
                   <button onClick={handleExcelExport} className="bg-emerald-600 text-white px-6 py-2.5 rounded-lg font-bold text-sm hover:bg-emerald-700 flex items-center gap-2 transition-all shadow-sm"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" strokeWidth="2"/></svg>엑셀 다운로드</button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="md:col-span-1 bg-white rounded-2xl shadow-sm border border-gray-100 p-6 h-fit">
                    <div className="flex justify-between items-center mb-6">
                      <button onClick={() => setCurrentCalendarMonth(new Date(currentCalendarMonth.getFullYear(), currentCalendarMonth.getMonth()-1, 1))} className="p-1 hover:bg-gray-100 rounded-full transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15 19l-7-7 7-7" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg></button>
                      <h4 className="font-bold text-sm text-gray-800">{currentCalendarMonth.getFullYear()}년 {currentCalendarMonth.getMonth()+1}월</h4>
                      <button onClick={() => setCurrentCalendarMonth(new Date(currentCalendarMonth.getFullYear(), currentCalendarMonth.getMonth()+1, 1))} className="p-1 hover:bg-gray-100 rounded-full transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 5l7 7-7 7" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg></button>
                    </div>
                    <div className="grid grid-cols-7 gap-1 place-items-center mb-2">
                      {['일','월','화','수','목','금','토'].map(d => <div key={d} className="text-[10px] font-bold text-gray-400 uppercase">{d}</div>)}
                    </div>
                    <div className="grid grid-cols-7 gap-1 place-items-center">{renderCalendar()}</div>
                  </div>

                  <div className="md:col-span-2 bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                    <div className="p-4 bg-gray-50 border-b border-gray-100 flex justify-between items-center">
                      <h4 className="font-bold text-sm text-gray-700">{selectedDate.toLocaleDateString('ko-KR')} 하교 리포트</h4>
                      <div className="relative">
                        <input type="text" placeholder="이름 검색..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="text-xs border border-gray-200 rounded-lg pl-8 pr-3 py-1.5 outline-none focus:ring-2 focus:ring-indigo-100 transition-all"/>
                        <svg className="w-3.5 h-3.5 text-gray-400 absolute left-2.5 top-1/2 -translate-y-1/2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
                      </div>
                    </div>
                    <div className="max-h-[500px] overflow-y-auto divide-y divide-gray-50 p-4 space-y-6">
                      {[1,2,3,4,5,6].map(g => {
                        const gradeStudents = studentsByGrade[g]?.filter(s => s.name.includes(searchTerm));
                        if (gradeStudents.length === 0) return null;
                        return (
                          <div key={g}>
                            <h5 className="text-[10px] font-bold text-indigo-400 mb-3 uppercase tracking-widest">{g}학년</h5>
                            <div className="grid grid-cols-1 gap-2">
                              {gradeStudents.map(s => {
                                const record = records.find(r => r.studentName === s.name && r.grade === g && isSameDate(new Date(r.timestamp), selectedDate));
                                return (
                                  <div key={s.id} className={`flex justify-between items-center p-3 rounded-xl border transition-all ${record ? 'bg-indigo-50 border-indigo-100' : 'bg-white border-gray-100 opacity-60'}`}>
                                    <div className="flex items-center gap-3">
                                      <div className={`w-1.5 h-1.5 rounded-full ${record ? 'bg-indigo-500' : 'bg-gray-300'}`}></div>
                                      <div>
                                        <div className="font-bold text-sm text-gray-900">{s.name}</div>
                                        <div className="text-[10px] text-indigo-500 font-medium">{record?.dismissalMethod || '미완료'}</div>
                                      </div>
                                    </div>
                                    {record && (
                                      <div className="flex items-center gap-4">
                                        <div className="text-right"><div className="text-xs font-bold text-gray-800">{new Date(record.timestamp).toLocaleTimeString('ko-KR', {hour:'2-digit', minute:'2-digit'})}</div></div>
                                        <button onClick={() => setRecordDeleteModal({isOpen: true, id: record.id, name: s.name})} className="text-red-300 hover:text-red-500 transition-colors p-1.5 hover:bg-white rounded-lg"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" strokeWidth="2"/></svg></button>
                                      </div>
                                    )}
                                  </div>
                                );
                              })}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              </div>
            ) : (
              /* ============ ROSTER MANAGEMENT (명단 관리) ============ */
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-fade-in">
                {[1,2,3,4,5,6].map(g => (
                  <div key={g} className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 flex flex-col h-full hover:shadow-md transition-shadow">
                    <div className="flex justify-between items-center mb-4">
                      <h4 className="text-lg font-bold text-gray-900">{g}학년 명단</h4>
                      <span className="text-xs text-indigo-500 font-bold bg-indigo-50 px-2 py-0.5 rounded-md">{studentsByGrade[g]?.length}명</span>
                    </div>

                    <div className="flex-1 flex flex-wrap gap-2 mb-6 min-h-[120px] content-start overflow-y-auto max-h-[300px] pr-2">
                      {studentsByGrade[g]?.map(s => (
                        <div key={s.id} className="group inline-flex items-center gap-2 bg-gray-50 text-gray-700 pl-3 pr-1.5 py-1.5 rounded-full text-sm font-medium border border-gray-200 hover:border-red-300 hover:bg-red-50 transition-all">
                          {s.name}
                          <button 
                            onClick={(e) => {
                              e.stopPropagation();
                              setRosterDeleteModal({ isOpen: true, student: s });
