                disabled={isDeleting} 
                onClick={() => setRecordDeleteModal({isOpen: false, id: null, name: ''})} 
                className="flex-1 py-3 text-gray-600 font-medium bg-gray-100 rounded-xl hover:bg-gray-200"
              >
                취소
              </button>
              <button 
                disabled={isDeleting} 
                onClick={handleConfirmRecordDelete} 
                className="flex-1 py-3 text-white font-bold bg-red-500 rounded-xl hover:bg-red-600 shadow-md"
              >
                {isDeleting ? '삭제 중...' : '기록 삭제'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

