export const fetchLunchMenu = async (date: Date): Promise<LunchData> => {
  // 날짜 키 생성 (예: 2024-05-20)
  const dateKey = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;

  // 1. 메모리 캐시 확인
  if (memoryCache[dateKey]) {
    console.log("Memory cache hit!");
    return memoryCache[dateKey];
  }

  // 2. Firestore 캐시 확인
  try {
    const cacheDoc = await getDoc(doc(db, "lunch_cache", dateKey));
    if (cacheDoc.exists()) {
      const data = cacheDoc.data() as LunchData;
      memoryCache[dateKey] = data; // 다음을 위해 메모리에도 저장
      console.log("Firestore cache hit!");
      return data;
    }
  } catch (e) {
    console.error("Cache check failed:", e);
  }

  // 3. 캐시가 없으면 Gemini AI 호출
  const formattedDate = date.toLocaleDateString('ko-KR', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    weekday: 'long',
  });

  const prompt = `
    전라남도 여수시에 위치한 '화양초등학교'의 ${formattedDate} 급식 메뉴를 알려줘.

    다음 규칙을 지켜줘:
    1. 메뉴는 보기 좋게 글머리 기호 등을 사용하여 목록 형태로 정리해줘.
    2. 만약 주말이나 공휴일이라 급식이 없다면 "오늘은 급식이 없는 날입니다"라고 명확히 말해줘.
    3. 열량(Kcal) 정보가 있다면 같이 표시해줘.
    4. 너무 긴 서론이나 불필요한 인사는 생략하고 핵심 정보 위주로 답변해줘.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "메뉴 정보를 가져올 수 없습니다.";

    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources: Source[] = chunks
      .map((chunk) => chunk.web)
      .filter((web): web is { title: string; uri: string } => 
        !!web && typeof web.title === 'string' && typeof web.uri === 'string'
      )
      .map((web) => ({
        title: web.title,
        uri: web.uri
      }));

    const uniqueSources = Array.from(
      new Map(sources.map((s) => [s.uri, s] as [string, Source])).values()
    );

    const lunchResult = {
      menuText: text,
      sources: uniqueSources,
    };

    // 4. 결과를 Firestore 및 메모리에 캐시 저장 (다음 요청을 위해)
    try {
      await setDoc(doc(db, "lunch_cache", dateKey), lunchResult);
      memoryCache[dateKey] = lunchResult;
    } catch (e) {
      console.error("Failed to save cache:", e);
    }

    return lunchResult;

  } catch (error) {
    console.error("Error fetching menu:", error);
    throw new Error("급식 정보를 불러오는 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.");
  }
};

