                className="flex-1 py-3 text-white font-bold bg-red-500 rounded-xl hover:bg-red-600 shadow-md"
              >
                {isDeleting ? '삭제 중...' : '기록 삭제'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

