import { GoogleGenAI } from "@google/genai";
import { LunchData, Source } from "../types";
import { db } from "./firebase";
import { doc, getDoc, setDoc, deleteDoc } from "firebase/firestore";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// 메모리 내 캐시 (앱 실행 중 속도 향상)
const memoryCache: Record<string, LunchData> = {};

export const generateGoodbyeMessage = async (name: string, grade: number): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Write a short, warm, and encouraging goodbye message (1-2 sentences) in Korean for a Korean elementary school student named ${name} (Grade ${grade}) who is leaving school right now. Mention resting well or having a good evening.`,
    });
    return response.text || "오늘 하루도 수고했어요! 조심히 들어가세요.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "하교가 완료되었습니다. 조심히 들어가세요!";
  }
};

export const fetchLunchMenu = async (date: Date, forceRefresh: boolean = false): Promise<LunchData> => {
  // 날짜 키 생성 (예: 2025-12-22)
  const currentYear = date.getFullYear();
  const dateKey = `${currentYear}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;

  // 1. 강제 새로고침이 아닌 경우에만 캐시 확인
  if (!forceRefresh) {
    if (memoryCache[dateKey]) {
      return memoryCache[dateKey];
    }

    try {
      const cacheDoc = await getDoc(doc(db, "lunch_cache", dateKey));
      if (cacheDoc.exists()) {
        const data = cacheDoc.data() as LunchData;
        memoryCache[dateKey] = data;
        return data;
      }
    } catch (e) {
      console.error("Cache check failed:", e);
    }
  } else {
    delete memoryCache[dateKey];
  }

  // 2. Gemini AI 호출 (2025년 기준 정밀 프롬프트)
  const formattedDate = `${date.getFullYear()}년 ${date.getMonth() + 1}월 ${date.getDate()}일 (${['일', '월', '화', '수', '목', '금', '토'][date.getDay()]}요일)`;

  const schoolUrl = "https://ys-hwayang.es.jne.kr/ys-hwayang_es/ad/fm/foodmenu/selectFoodMenuView.do?mi=155714";

  const prompt = `
    전라남도 여수시에 위치한 '화양초등학교'의 공식 홈페이지(${schoolUrl})를 참조해서 **${formattedDate}**의 급식 메뉴를 알려줘.

    **검색 및 분석 지침:**
    1. 현재 연도는 **${date.getFullYear()}년**이야. 절대로 2024년이나 다른 연도의 데이터를 가져오지 마.
    2. 홈페이지의 급식 달력(식단표)에서 **${date.getMonth() + 1}월 ${date.getDate()}일** 칸에 적힌 텍스트를 정확하게 읽어줘.
    3. 특히 12월 22일(월), 12월 24일(수), 12월 26일(금)의 메뉴가 서로 섞이지 않도록 주의 깊게 확인해.
    4. 만약 해당 날짜에 메뉴 정보가 없다면 "홈페이지에 등록된 급식 정보가 없습니다"라고 알려줘. 
    5. 메뉴는 불필요한 수식어 없이 요리 이름들을 목록(List) 형태로 깔끔하게 정리해줘.
    6. 칼로리(Kcal)와 알레르기 유발 식품 정보가 적혀 있다면 함께 포함해줘.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "메뉴 정보를 가져올 수 없습니다.";

    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources: Source[] = chunks
      .map((chunk) => chunk.web)
      .filter((web): web is { title: string; uri: string } => 
        !!web && typeof web.title === 'string' && typeof web.uri === 'string'
      )
      .map((web) => ({
        title: web.title,
        uri: web.uri
      }));

    const uniqueSources = Array.from(
      new Map(sources.map((s) => [s.uri, s] as [string, Source])).values()
    );

    const lunchResult = {
      menuText: text,
      sources: uniqueSources,
    };

    // 3. 결과를 캐시에 저장
    try {
      await setDoc(doc(db, "lunch_cache", dateKey), lunchResult);
      memoryCache[dateKey] = lunchResult;
    } catch (e) {
      console.error("Failed to save cache:", e);
    }

    return lunchResult;

  } catch (error) {
    console.error("Error fetching menu:", error);
    throw new Error("급식 정보를 불러오는 중 오류가 발생했습니다.");
  }
};

