              <p className="text-sm font-semibold text-indigo-600 bg-indigo-50 inline-block px-3 py-1 rounded-full">{new Date().toLocaleDateString('ko-KR', { month: 'long', day: 'numeric', weekday: 'short' })}</p>
              <h2 className="text-2xl font-bold text-gray-900">하교 시간 기록하기</h2>
            </div>

            <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
