  const [exportEndDate, setExportEndDate] = useState(formatDateForInput(new Date()));

  // 모달 관련 상태
  const [recordDeleteModal, setRecordDeleteModal] = useState<{isOpen: boolean, id: string | null, name: string}>({ isOpen: false, id: null, name: '' });
  const [rosterDeleteModal, setRosterDeleteModal] = useState<{isOpen: boolean, student: Student | null}>({ isOpen: false, student: null });
  const [isDeleting, setIsDeleting] = useState(false);

