                <div className="flex items-center gap-3 bg-white/10 rounded-full px-1 py-1 border border-white/5">
                  <button onClick={() => changeLunchDate(-1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-white/20 transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15 19l-7-7 7-7" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg></button>
