                </div>
              </div>

              {lunchLoading ? (
                <div className="space-y-4 py-4">
                  <div className="animate-pulse space-y-3">
                    <div className="h-4 bg-white/10 rounded-full w-3/4"></div>
                    <div className="h-4 bg-white/10 rounded-full w-full"></div>
                    <div className="h-4 bg-white/10 rounded-full w-2/3"></div>
                  </div>
                  <div className="flex flex-col items-center gap-2 pt-4">
                    <div className="w-6 h-6 border-2 border-white/20 border-t-white rounded-full animate-spin"></div>
                    <p className="text-[11px] text-center text-white/50 leading-snug">
                      학교 홈페이지 식단표의<br/>다음 페이지까지 정밀 분석 중입니다...
                    </p>
                  </div>
                </div>
              ) : (
                <div className="space-y-4">
                  <div className="text-sm bg-white/10 p-4 rounded-xl backdrop-blur-sm whitespace-pre-wrap leading-relaxed animate-fade-in min-h-[120px] border border-white/5">
                    {lunchInfo?.menuText || "해당 날짜의 식단 정보가 없습니다."}
                  </div>
                  {lunchInfo?.sources && lunchInfo.sources.length > 0 && (
                    <div className="flex flex-wrap gap-2 pt-2 border-t border-white/10">
                      <a href={lunchInfo.sources[0].uri} target="_blank" rel="noopener noreferrer" className="text-[10px] text-white/40 hover:text-white underline truncate max-w-full transition-colors">
                        출처: 화양초등학교 공식 홈페이지
                      </a>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        ) : (
          /* ============ TEACHER VIEW ============ */
          <div className="space-y-6 animate-fade-in">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">선생님 관리 모드</h2>
                <p className="text-gray-500 text-sm">학생 명단과 하교 기록을 효율적으로 관리하세요.</p>
              </div>
              <div className="flex bg-indigo-50 p-1 rounded-xl">
                <button onClick={() => setTeacherView('DASHBOARD')} className={`px-4 py-2 text-sm font-bold rounded-lg transition-all ${teacherView === 'DASHBOARD' ? 'bg-indigo-600 text-white shadow-md' : 'text-indigo-400'}`}>현황 대시보드</button>
                <button onClick={() => setTeacherView('ROSTER')} className={`px-4 py-2 text-sm font-bold rounded-lg transition-all ${teacherView === 'ROSTER' ? 'bg-indigo-600 text-white shadow-md' : 'text-indigo-400'}`}>명단 관리</button>
