import { GoogleGenAI } from "@google/genai";
import { LunchData, Source } from "../types";
import { db } from "./firebase";
import { doc, getDoc, setDoc, deleteDoc } from "firebase/firestore";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// 메모리 내 캐시
const memoryCache: Record<string, LunchData> = {};

export const generateGoodbyeMessage = async (name: string, grade: number): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Write a short, warm, and encouraging goodbye message (1-2 sentences) in Korean for a Korean elementary school student named ${name} (Grade ${grade}) who is leaving school right now. Mention resting well or having a good evening.`,
    });
    return response.text || "오늘 하루도 수고했어요! 조심히 들어가세요.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "하교가 완료되었습니다. 조심히 들어가세요!";
  }
};

export const fetchLunchMenu = async (date: Date, forceRefresh: boolean = false): Promise<LunchData> => {
  const currentYear = date.getFullYear();
  const dateKey = `${currentYear}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;

  if (!forceRefresh) {
    if (memoryCache[dateKey]) return memoryCache[dateKey];
    try {
      const cacheDoc = await getDoc(doc(db, "lunch_cache", dateKey));
      if (cacheDoc.exists()) {
        const data = cacheDoc.data() as LunchData;
        memoryCache[dateKey] = data;
        return data;
      }
    } catch (e) { console.error("Cache check failed:", e); }
  } else {
    delete memoryCache[dateKey];
  }

  const year = date.getFullYear();
  const month = date.getMonth() + 1;
  const day = date.getDate();
  const dayName = ['일', '월', '화', '수', '목', '금', '토'][date.getDay()];
  const formattedDate = `${year}년 ${month}월 ${day}일 (${dayName}요일)`;

  // 사용자로부터 확인된 힌트 정보 (검색 시 정확도 향상을 위해 사용)
  const menuHint = "현미수수밥, 사골황태국, 계란장조림, 미역줄기팽이버섯볶음, 배추전/양념장, 돼지목살고추장구이, 배추김치, 친환경야채쌈";

  const prompt = `
    전남 여수 '화양초등학교'의 **${formattedDate}** 급식 정보를 정밀하게 검색해서 알려줘.

    **반드시 참고해야 할 최우선 소스:**
    1. **식품안전나라 (foodsafetykorea.go.kr)**: '우리학교찾기' 기능을 통해 전남 여수 화양초등학교의 월간 식단표 데이터를 조회해.
    2. **NEIS 공공데이터 (open.neis.go.kr)**: 교육행정정보시스템에 등록된 화양초등학교(전남교육청 소속)의 급식 정보를 찾아내.
    3. **학교 공식 홈페이지**: https://ys-hwayang.es.jne.kr/

    **검색 및 검증 가이드:**
    - 조회 년도는 반드시 **2025년**이어야 해.
    - **12월 26일(금)** 메뉴 확인: 이 날은 "${menuHint}" 메뉴가 이미 확정되어 있어. 만약 검색 결과에서 이 메뉴 구성이 보인다면 그 소스는 매우 정확한 거야.
    - 식품안전나라 웹사이트 내에서 검색 엔진이 인덱싱한 페이지들을 샅샅이 뒤져서 해당 날짜의 메뉴를 추출해.
    - 주간 식단표가 아닌 '월간 식단표'나 '식단 상세보기' 페이지를 타겟팅해서 검색해줘.

    **출력 형식:**
    - 식단 메뉴(요리명)를 글머리 기호(•)와 함께 나열해줘.
    - 칼로리(Kcal)와 알레르기 유발 식품 번호 정보도 포함해줘.
    - 정보를 찾았다면 출처 링크(URL)를 반드시 groundingMetadata에서 추출해서 포함해.
    - 만약 정말로 정보가 없다면 "홈페이지나 식품안전나라에 아직 등록되지 않은 날짜입니다"라고 답변해줘.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview", // 검색 도구와 함께 사용하기에 최적화됨
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "메뉴 정보를 가져올 수 없습니다.";

    // 출처 URL 추출
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources: Source[] = chunks
      .map((chunk) => chunk.web)
      .filter((web): web is { title: string; uri: string } => 
        !!web && typeof web.title === 'string' && typeof web.uri === 'string'
      )
      .map((web) => ({
        title: web.title,
        uri: web.uri
      }));

    // 중복 제거 및 식품안전나라/학교홈페이지 우선순위 정렬
    const uniqueSources = Array.from(
      new Map(sources.map((s) => [s.uri, s] as [string, Source])).values()
    ).sort((a, b) => {
      if (a.uri.includes('foodsafetykorea') || a.uri.includes('jne.go.kr')) return -1;
      return 1;
    });

    const lunchResult = {
      menuText: text,
      sources: uniqueSources,
    };

    // 성공적인 결과만 캐싱
    if (!text.includes("등록되지 않은") && !text.includes("가져올 수 없습니다")) {
      try {
        await setDoc(doc(db, "lunch_cache", dateKey), lunchResult);
        memoryCache[dateKey] = lunchResult;
      } catch (e) { console.error("Failed to save cache:", e); }
    }

    return lunchResult;

  } catch (error) {
    console.error("Error fetching menu with Search Grounding:", error);
    throw new Error("급식 정보를 불러오는 중 오류가 발생했습니다.");
  }
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
