                </div>
                <button onClick={() => changeLunchDate(1)} className="w-10 h-10 flex items-center justify-center rounded-xl hover:bg-white/10 transition-colors"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M9 5l7 7-7 7" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/></svg></button>
              </div>

              {lunchLoading ? (
                <div className="py-12 flex flex-col items-center justify-center gap-4">
                  <div className="w-10 h-10 border-4 border-white/10 border-t-white rounded-full animate-spin"></div>
                  <div className="text-center">
                    <p className="text-sm font-bold text-white/80 mb-1">식품안전나라 상세 분석 중</p>
                    <p className="text-[10px] text-white/40 leading-relaxed px-4">홈페이지 버튼 구조를 우회하여 <br/> 상세 식단표를 추적하고 있습니다...</p>
