              ) : (
                <div className="space-y-6">
                  <div className="bg-white/10 rounded-2xl p-5 backdrop-blur-md border border-white/10 min-h-[160px] animate-fade-in">
                    <div className="text-[14px] leading-[1.8] font-medium text-white/90 whitespace-pre-wrap">
                      {lunchInfo?.menuText || "해당 날짜에 등록된 식단 정보가 없습니다."}
                    </div>
                  </div>

                  <div className="pt-2">
                    <a 
                      href="https://ys-hwayang.es.jne.kr/ys-hwayang_es/ad/fm/foodmenu/selectFoodMenuView.do?mi=155714" 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="flex items-center justify-between bg-white text-indigo-600 px-4 py-3 rounded-2xl font-bold text-xs hover:bg-indigo-50 transition-colors shadow-lg"
                    >
                      <span>학교 공식 식단표 직접보기</span>
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
                    </a>
                  </div>

                  {lunchInfo?.sources && lunchInfo.sources.length > 0 && (
                    <div className="flex flex-col gap-1 px-1">
                      <span className="text-[9px] text-white/30 font-bold tracking-widest uppercase">Verified Source Logs</span>
                      {lunchInfo.sources.slice(0, 2).map((s, i) => (
                        <div key={i} className="text-[9px] text-white/40 truncate">
                          • {s.title}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        ) : (
          /* ============ TEACHER VIEW ============ */
          <div className="space-y-6 animate-fade-in">
             <div className="text-center p-12 bg-white rounded-3xl shadow-sm border border-gray-100">
               <h2 className="text-xl font-bold text-gray-900 mb-4">선생님 관리 모드</h2>
               <p className="text-gray-500 mb-8">상단의 탭을 클릭하여 대시보드나 명단 관리를 시작해 주세요.</p>
               <div className="flex justify-center gap-4">
                 <button onClick={() => setTeacherView('DASHBOARD')} className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold">대시보드</button>
                 <button onClick={() => setTeacherView('ROSTER')} className="bg-indigo-50 text-indigo-600 px-6 py-2 rounded-xl font-bold">명단 관리</button>
               </div>
             </div>
          </div>
        )}
      </main>
    </div>
  );
}

