                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Export Card */}
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 flex flex-wrap items-center justify-between gap-4">
        <div className="flex flex-wrap items-center gap-4">
          <div className="flex items-center gap-2">
            <span className="text-[10px] font-bold text-gray-400">시작</span>
            <input type="date" value={exportStartDate} onChange={e => setExportStartDate(e.target.value)} className="bg-gray-50 border-none rounded-xl text-sm p-2 font-bold focus:ring-2 focus:ring-indigo-100" />
          </div>
          <div className="flex items-center gap-2">
            <span className="text-[10px] font-bold text-gray-400">종료</span>
            <input type="date" value={exportEndDate} onChange={e => setExportEndDate(e.target.value)} className="bg-gray-50 border-none rounded-xl text-sm p-2 font-bold focus:ring-2 focus:ring-indigo-100" />
