        <button onClick={handleExport} className="bg-indigo-600 text-white px-8 py-3 rounded-2xl font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>
          엑셀로 저장
        </button>
      </div>
    </div>
  );

  const renderRoster = () => (
    <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6 animate-fade-in">
      {[1,2,3,4,5,6].map(g => (
        <div key={g} className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden flex flex-col">
          <div className="p-5 bg-gray-50 border-b border-gray-100 flex justify-between items-center">
            <h4 className="font-black text-gray-900">{g}학년 명단</h4>
            <span className="text-xs font-bold text-gray-400">{studentsByGrade[g]?.length || 0}명</span>
          </div>
          <div className="p-5 space-y-4 flex-1">
            <div className="flex flex-wrap gap-2">
              {studentsByGrade[g]?.map(s => (
