               </div>
            </div>
          </div>
        ) : (
          <div className="space-y-8">
            <div className="flex justify-between items-end">
              <div className="space-y-1">
                <h2 className="text-4xl font-black text-gray-900 tracking-tight">관리자 센터</h2>
              </div>
              <div className="flex bg-white p-1.5 rounded-2xl shadow-sm border border-gray-100">
                <button onClick={() => setTeacherView('DASHBOARD')} className={`px-6 py-2.5 rounded-xl text-sm font-black transition-all ${teacherView === 'DASHBOARD' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-gray-400'}`}>대시보드</button>
                <button onClick={() => setTeacherView('ROSTER')} className={`px-6 py-2.5 rounded-xl text-sm font-black transition-all ${teacherView === 'ROSTER' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-gray-400'}`}>명단 관리</button>
              </div>
