                    <div key={s.id} className={`p-5 rounded-2xl border transition-all flex justify-between items-center group relative ${isDone ? 'bg-indigo-50/50 border-indigo-100' : 'bg-gray-50/50 border-transparent hover:bg-gray-100'}`}>
                      <div>
                        <p className={`font-black text-base ${isDone ? 'text-indigo-900' : 'text-gray-400'}`}>{s.name}</p>
                        <p className="text-[10px] text-gray-400 mt-1 font-bold">{isDone ? new Date(record.timestamp).toLocaleTimeString('ko-KR', { hour: '2-digit', minute: '2-digit' }) : '-'}</p>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className={`px-3 py-1.5 rounded-xl text-[10px] font-black uppercase ${isDone ? 'bg-white text-indigo-600 shadow-sm' : 'bg-gray-100 text-gray-300'}`}>
