  const renderRoster = () => (
    <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6 animate-fade-in">
      {[1,2,3,4,5,6].map(g => (
        <div key={g} className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden flex flex-col">
          <div className="p-5 bg-gray-50 border-b border-gray-100 flex justify-between items-center">
            <h4 className="font-black text-gray-900">{g}학년 명단</h4>
            <span className="text-xs font-bold text-gray-400">{studentsByGrade[g]?.length || 0}명</span>
          </div>
          <div className="p-5 space-y-4 flex-1">
            <div className="flex flex-wrap gap-2">
              {studentsByGrade[g]?.map(s => (
                <div key={s.id} className="flex items-center gap-1 bg-gray-50 border border-gray-100 pl-3 pr-1 py-1 rounded-full group">
                  <span className="text-xs font-bold text-gray-700">{s.name}</span>
                  <button onClick={() => setDeleteModal({ isOpen: true, type: 'STUDENT', id: s.id, name: s.name })} className="p-1 text-gray-300 hover:text-red-500 rounded-full hover:bg-white transition-all">
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/></svg>
                  </button>
