            <button onClick={() => setRole('STUDENT')} className={`px-5 py-2 text-xs font-bold rounded-xl transition-all ${role === 'STUDENT' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>학생용</button>
