                          <span key={s.id} className={`px-4 py-2 rounded-2xl text-[13px] font-bold transition-all ${isDone ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'bg-gray-100 text-gray-300'}`}>
