                  return (
                    <div key={s.id} className={`p-4 rounded-xl border transition-all flex items-center group relative ${isDone ? 'bg-indigo-50/50 border-indigo-100 shadow-sm' : 'bg-gray-50/50 border-transparent hover:bg-gray-100'}`}>
